#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char *argv[]) {
    const char *input;
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }
    input = argv[1];
    size_t len = strlen(input);
    if (len > 1024) len = 1024; // limit as observed in the binary
    char out[1025]; // buffer for trimmed output
    size_t out_idx = 0;
    int started = 0;      // indicates we have output at least one non‑whitespace character
    int prev_space = 0;   // true if the previous character processed was whitespace

    for (size_t i = 0; i < len; ++i) {
        char c = input[i];
        int is_space = (c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\v' || c == '\f');
        if (is_space) {
            if (!started) {
                // skip leading whitespace
                continue;
            }
            // remember that we saw whitespace; a single space will be emitted before the next non‑whitespace character
            prev_space = 1;
        } else {
            if (prev_space && out_idx > 0) {
                out[out_idx++] = ' ';
            }
            out[out_idx++] = c;
            started = 1;
            prev_space = 0;
        }
    }
    out[out_idx] = '\0';
    if (out_idx == 0) {
        puts("EMPTY");
    } else {
        puts(out);
    }
    return 0;
}
